KG42.register("nodes-629a3a309c22a336640acb78",{"id":"COMP-234e316a4df6b1c7","code":"BID016","label":"Demand-description submission and cross-market forwarding of allocated quantities","definition":"The market participation agent, according to the demand representation rules specified by the source, submits electricity demand with an explicit basis as a demand-side clearing input to the receiving market.","layer":"L3","template_code":"JOC","concept_id":"bidding.demand","concept_ids":["bidding.demand"],"identity_dimensions":{"definition":"The market participation agent, according to the demand representation rules specified by the source, submits electricity demand with an explicit basis as a demand-side clearing input to the receiving market.","object":"Electricity demand declaration information with an explicit source and representation rules.","inputs":"The demand basis specified by the source and its representation conditions.","operation":"Construct and submit the demand declaration according to the specified representation relation; the specific aggregation and forwarding procedures are retained by the members.","outputs":"Individual or aggregated demand declarations of the receiving market.","boundary":"Retain the demand-side identity and L3/JOC representation and submission boundary of COMP-1e227d383daa7d23; exclude allocated quantity generation, demand allocation, or pricing."},"exclusions":[["The submitter is the aggregator.","Non-deferrable load uses a demand function.","Deferrable load uses a multi-part bid containing energy demand and technical constraints."],["The submitter is LA; the direction is from the DNEM allocated quantity to WEM bus demand.","The declaration depends on the dispatch result already obtained.","The reverse submission in the complete quotation does not expand the target projection of this member."],["Microgrids and possibly other responsive loads submit; the DMO receives, aggregates, and reports to the ISO.","The bid is monotonically decreasing; under normal operation, the fixed portion must be supplied in full and cannot be changed.","Fixed load is aggregated according to D^f_t=∑_m d^f_{mt}; each response segment retains DX^{max}_{mj}.","Response capability may come from load curtailment or local DER; the allocated quantity DX_{mjt} and subsequent allocation optimization are not declaration fields."]],"members":[{"id":"18-dlmp_analysis::v141-c-R004::V::bidding.demand","rule_id":"v141-c-R004","market_meaning":"Aggregators submit demand functions for non-deferrable loads. Scope: Aggregator demand submissions in the distribution-market clearing procedure. Condition: For non-deferrable loads. Aggregators submit multi-part bids representing the energy requirements and technical constraints of deferrable loads. Scope: Aggregator demand submissions in the distribution-market clearing procedure. Condition: For deferrable loads.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Aggregator demand submissions in the distribution-market clearing procedure.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E004"]},"constraint_refs":["18-dlmp_analysis::v141-c-R004::v141-c-R004-C001","18-dlmp_analysis::v141-c-R004::v141-c-R004-C002"],"decision_anchor":"bidding.demand","source_rule_sha256":"82bd0c452b67222caf74aaeb26469a61f6ce0168bf59fb8a2ee30e4fd27a04fa","paper":"18-dlmp_analysis","rule_ref":"18-dlmp_analysis::v141-c-R004","node_id":"bidding.demand","function":"bidding.demand","unit_id":"18-dlmp_analysis::v141-a-M02::bidding.demand","mechanism_id":"v141-a-M02","anchor":true},{"id":"23-hierarchical_market_structure::v141-c-R007::V::bidding.demand","rule_id":"v141-c-R007","market_meaning":"The LA presents the dispatch awarded by DNEM clearing as a demand quantity at its WEM bus. Scope: LA-mediated submission of DNEM-awarded dispatch as demand at the LA's WEM bus.","omega":{"market_type":"LEM_DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"LA-mediated submission of DNEM-awarded dispatch as demand at the LA's WEM bus.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E005"]},"constraint_refs":["23-hierarchical_market_structure::v141-c-R007::v141-c-R007-C001"],"decision_anchor":"bidding.demand","source_rule_sha256":"fcf96e61e513dea89a7d47c24fcc9e106c145b9c86d8ea77914f447a81629e74","paper":"23-hierarchical_market_structure","rule_ref":"23-hierarchical_market_structure::v141-c-R007","node_id":"bidding.demand","function":"bidding.demand","unit_id":"23-hierarchical_market_structure::v141-a-M01::bidding.demand","mechanism_id":"v141-a-M01","anchor":true},{"id":"34-market_versus_price_scheduling::v141-c-R002::V::bidding.demand","rule_id":"v141-c-R002","market_meaning":"The DMO combines received demand bids and submits an aggregated demand bid to the ISO. Scope: DMO aggregation of microgrid and other responsive-load demand bids for submission to the ISO. Microgrid demand bids take a monotonically decreasing form. Scope: Microgrid demand submissions to the DMO. The fixed nonresponsive-load portion of the demand bid cannot be altered. Scope: The fixed nonresponsive-load quantity in a microgrid demand bid. Condition: Under normal operation conditions.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"DMO aggregation of microgrid and other responsive-load demand bids for submission to the ISO. | Microgrid demand submissions to the DMO. | The fixed nonresponsive-load quantity in a microgrid demand bid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e011","v141-b-g01-e037","v141-b-g02-E16"]},"constraint_refs":["34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C001","34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C002","34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C003","34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C004"],"decision_anchor":"bidding.demand","source_rule_sha256":"d98c89cdf0dde2f3a8a6112ca06bc6e5647ab0f9c9f9d58535814c9da2b56144","paper":"34-market_versus_price_scheduling","rule_ref":"34-market_versus_price_scheduling::v141-c-R002","node_id":"bidding.demand","function":"bidding.demand","unit_id":"34-market_versus_price_scheduling::v141-a-M01::bidding.demand","mechanism_id":"v141-a-M01","anchor":true},{"id":"34-market_versus_price_scheduling::v141-c-R003::V::bidding.demand","rule_id":"v141-c-R003","market_meaning":"Submitted microgrid demand bids provide the inputs on which the DMO bases its local power allocations. Scope: DMO quantity disaggregation among microgrids within its service territory. Condition: Once the ISO has determined the power awarded to the DMO. The maximum quantities in submitted demand-bid segments limit the quantities awarded to those segments. Scope: Responsive demand-bid segment allocations in DMO quantity disaggregation. Condition: Once the ISO has determined the power awarded to the DMO. The DMO performs local allocation by disaggregating its awarded power among microgrids in its service territory. Scope: Allocation of the DMO's awarded power among microgrids in its service territory. Condition: Once the ISO has determined the power awarded to the DMO. Local quantity disaggregation maximizes objective (12), the sum of c_{mj} DX_{mjt} over times, microgrids and bid segments. Scope: DMO quantity-disaggregation optimization within its service territory. Condition: Once the ISO has determined the power awarded to the DMO. Local allocation must fully supply the fixed nonresponsive load represented in each microgrid's bid; that fixed load cannot be altered. Scope: Fixed nonresponsive load represented in microgrid demand bids submitted to the DMO. Condition: Under normal operation conditions. Each microgrid's responsive allocation equals the sum of its dispatched segment quantities, and its total award equals fixed plus responsive load. All microgrid awards sum to the quantity awarded by the ISO to the DMO. Scope: Hourly accounting of DMO power allocations among microgrids in its service territory. Condition: Once the ISO has determined the power awarded to the DMO.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Allocation of the DMO's awarded power among microgrids in its service territory. | DMO quantity disaggregation among microgrids within its service territory. | DMO quantity-disaggregation optimization within its service territory. | Fixed nonresponsive load represented in microgrid demand bids submitted to the DMO. | Hourly accounting of DMO power allocations among microgrids in its service territory. | Responsive demand-bid segment allocations in DMO quantity disaggregation.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e033","v141-b-g01-e034","v141-b-g01-e035","v141-b-g01-e036","v141-b-g02-E16"]},"constraint_refs":["34-market_versus_price_scheduling::v141-c-R003::v141-c-R003-C001","34-market_versus_price_scheduling::v141-c-R003::v141-c-R003-C002"],"decision_anchor":"clearing.local","source_rule_sha256":"ae330c220c9fd0e1cf40e9ec0db7bf57a00793801d2710af7b8b4588d14fdef7","paper":"34-market_versus_price_scheduling","rule_ref":"34-market_versus_price_scheduling::v141-c-R003","node_id":"bidding.demand","function":"bidding.demand","unit_id":"34-market_versus_price_scheduling::v141-a-M01::bidding.demand","mechanism_id":"v141-a-M01","anchor":false},{"id":"34-market_versus_price_scheduling::v141-c-R004::V::bidding.demand","rule_id":"v141-c-R004","market_meaning":"The ISO's social-welfare clearing objective applies when it considers demand bids. Scope: ISO system-level clearing within the DMO-mediated market-based scheduling arrangement. Condition: When the ISO considers demand bids. The ISO maximizes system social welfare, described as consumption payments minus generation costs, subject to power balance, unit constraints, transmission line limits, and transmission line power flow constraints. Scope: ISO system-level bid-based clearing within the DMO-mediated market-based scheduling arrangement. Condition: When the ISO considers demand bids.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"ISO system-level bid-based clearing within the DMO-mediated market-based scheduling arrangement. | ISO system-level clearing within the DMO-mediated market-based scheduling arrangement.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E21","v141-b-g02-E23"]},"constraint_refs":["34-market_versus_price_scheduling::v141-c-R004::v141-c-R004-C001"],"decision_anchor":"clearing.social_welfare","source_rule_sha256":"c71f84e4f9bebea3d00a8e31ab1798bcbfed50d8572d2a578c5d0fb80262b9aa","paper":"34-market_versus_price_scheduling","rule_ref":"34-market_versus_price_scheduling::v141-c-R004","node_id":"bidding.demand","function":"bidding.demand","unit_id":"34-market_versus_price_scheduling::v141-a-M01::bidding.demand","mechanism_id":"v141-a-M01","anchor":false},{"id":"34-market_versus_price_scheduling::v141-c-R005::V::bidding.demand","rule_id":"v141-c-R005","market_meaning":"The DMO receives demand bids submitted by microgrids and other responsive loads, if any. Scope: Demand-bid receipt in the DMO-administered distribution market, covering microgrids and other responsive loads if any. The DMO may be formed as a new entity or as part of existing electric utilities. Scope: Institutional formation of the proposed DMO. An independent DMO may establish a universal market environment instead of a separate environment for each utility. Scope: Market establishment by an independent DMO. Condition: The DMO is independent.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Demand-bid receipt in the DMO-administered distribution market, covering microgrids and other responsive loads if any. | Institutional formation of the proposed DMO. | Market establishment by an independent DMO.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e011","v141-b-g02-E02"]},"constraint_refs":["34-market_versus_price_scheduling::v141-c-R005::v141-c-R005-C001"],"decision_anchor":"coordination.local_operator","source_rule_sha256":"87b82451f61ecc37c9ca2ef2fa4fdff8af0624843a1cc0ef6aa8a1c2f8baa3d8","paper":"34-market_versus_price_scheduling","rule_ref":"34-market_versus_price_scheduling::v141-c-R005","node_id":"bidding.demand","function":"bidding.demand","unit_id":"34-market_versus_price_scheduling::v141-a-M01::bidding.demand","mechanism_id":"v141-a-M01","anchor":false}],"paper_ids":["18-dlmp_analysis","23-hierarchical_market_structure","34-market_versus_price_scheduling"],"evidence":[{"evidence_id":"v141-b-g01-E004","location":{"location_id":"src-b1966ef5f7-p02-c1r1__v141-a-M02-bidding","page":2,"printed_page":null,"section":"I. Introduction","anchor_text":"PAPAVASILIOU: ANALYSIS OF DISTRIBUTION LOCATIONAL MARGINAL PRICES clearing: (i) aggregators submit d","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"clearing: (i) aggregators submit demand functions for non-deferrable loads and multi-part bids for deferrable loads that represent the energy requirements and technical constraints of deferrable loads","paper":"18-dlmp_analysis","rule_id":"v141-c-R004","quote":"clearing: (i) aggregators submit demand functions for non-deferrable loads and multi-part bids for deferrable loads that represent the energy requirements and technical constraints of deferrable loads"},{"evidence_id":"v141-b-g01-E005","location":{"location_id":"src-fbc18f73e3-p03-c1r3__v141-a-M01-participation","page":3,"printed_page":null,"section":"I. Introduction","anchor_text":"composed of these markets. Here, each market participant bids in associated electricity market, whil","equation_id":null,"figure_id":"Fig. 1","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Fig. 1 shows the proposed hierarchical market structure that composed of these markets. Here, each market participant bids in associated electricity market, while each LA is an intermediate agent that participates in both markets to address the synergy of the two markets. The LA bids in the WEM and presents the awarded dispatch in the DNEM as demand on its bus in the WEM. The ISO clears the market and provide the awarded dispatch for the LA and LMP at the LAs bus. The LA bids in the DNEM and presents the awarded dispatch in the WEM as demand on its bus in the DNEM. The DNO clears the market and provide the awarded dispatch for the LA and the market clearing price (MCP) of the market.","paper":"23-hierarchical_market_structure","rule_id":"v141-c-R007","quote":"Fig. 1 shows the proposed hierarchical market structure that composed of these markets. Here, each market participant bids in associated electricity market, while each LA is an intermediate agent that participates in both markets to address the synergy of the two markets. The LA bids in the WEM and presents the awarded dispatch in the DNEM as demand on its bus in the WEM. The ISO clears the market and provide the awarded dispatch for the LA and LMP at the LAs bus. The LA bids in the DNEM and presents the awarded dispatch in the WEM as demand on its bus in the DNEM. The DNO clears the market and provide the awarded dispatch for the LA and the market clearing price (MCP) of the market."},{"evidence_id":"v141-b-g01-e009","location":{"location_id":"src-b66ae5184e-p03-c2r3__v141-a-M01-bidding","page":3,"printed_page":null,"section":"III. Model Outline","anchor_text":"nd, The discussed DMO in this paper is a platform that enables ts, market activities for end-use cus","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Two major responsibilities of the DMO within this structure are: 1) To receive demand bids from the microgrids (and other responsive loads if any), combine them, and offer an aggregated bid to the ISO...","paper":"34-market_versus_price_scheduling","rule_id":"v141-c-R002","quote":"Two major responsibilities of the DMO within this structure are: 1) To receive demand bids from the microgrids (and other responsive loads if any), combine them, and offer an aggregated bid to the ISO..."},{"evidence_id":"v141-b-g01-e037","location":{"location_id":"src-b66ae5184e-p05-c2r2__v141-a-M01-bidding","page":5,"printed_page":null,"section":"B. DMO / 1) Bid Aggregation","anchor_text":"ed is o- Fig. 2. Demand bid curve for microgrid m with a three-segment bid. by B. DMO nal es The DMO","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"The DMO seeks two objectives: first, to combine individual bids received from microgrids in its territory to create an aggregated bid and accordingly send the aggregated bid to the ISO to participate in the energy market; second, to disaggregate the awarded quantity by the ISO to individual microgrids in accordance with their respective bids.","paper":"34-market_versus_price_scheduling","rule_id":"v141-c-R002","quote":"The DMO seeks two objectives: first, to combine individual bids received from microgrids in its territory to create an aggregated bid and accordingly send the aggregated bid to the ISO to participate in the energy market; second, to disaggregate the awarded quantity by the ISO to individual microgrids in accordance with their respective bids."},{"evidence_id":"v141-b-g01-e011","location":{"location_id":"src-b66ae5184e-p03-c2r4__v141-a-M01-bidding","page":3,"printed_page":null,"section":"III. Model Outline","anchor_text":"li- vice territory, and subsequently determine microgrids shares ia, from the awarded power. Microgr","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Microgrids would submit their bids to the DMO (in the form of monotonically decreasing demand bids) and later be notified by the DMO on the amount of awarded power (henceforth referred to as the assigned power).","paper":"34-market_versus_price_scheduling","rule_id":"v141-c-R002","quote":"Microgrids would submit their bids to the DMO (in the form of monotonically decreasing demand bids) and later be notified by the DMO on the amount of awarded power (henceforth referred to as the assigned power)."},{"evidence_id":"v141-b-g02-E16","location":{"location_id":"src-b66ae5184e-p05-c2r2__v141-a-M01-bidding","page":5,"printed_page":null,"section":"B. DMO / 1) Bid Aggregation","anchor_text":"ed is o- Fig. 2. Demand bid curve for microgrid m with a three-segment bid. by B. DMO nal es The DMO","equation_id":"Eq. (11)","figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Fig. 2 depicts a typical demand bid curve submitted by a microgrid to the DMO at a specific hour t. The bid consists of fixed and variable parts. The fixed part shows the microgrid nonresponsive load which must be fully supplied under normal operation conditions and cannot be altered. The variable part, on the other hand, shows the microgrid flexibility in reducing its consumption from its total load. It consists of several segments. The reduction in consumption can be achieved either via load curtailment or local DER generation. The DMO combines the individual microgrid bids and obtains an aggregated bid to be sent to the ISO. The fixed loads are collectively added to obtain the total fixed load in the DMO service territory (11).","paper":"34-market_versus_price_scheduling","rule_id":"v141-c-R002","quote":"Fig. 2 depicts a typical demand bid curve submitted by a microgrid to the DMO at a specific hour t. The bid consists of fixed and variable parts. The fixed part shows the microgrid nonresponsive load which must be fully supplied under normal operation conditions and cannot be altered. The variable part, on the other hand, shows the microgrid flexibility in reducing its consumption from its total load. It consists of several segments. The reduction in consumption can be achieved either via load curtailment or local DER generation. The DMO combines the individual microgrid bids and obtains an aggregated bid to be sent to the ISO. The fixed loads are collectively added to obtain the total fixed load in the DMO service territory (11)."},{"evidence_id":"v141-b-g01-e032","location":{"location_id":"src-b66ae5184e-p05-c2r3__v141-a-M01-bidding","page":5,"printed_page":null,"section":"B. DMO / 1) Bid Aggregation","anchor_text":"or be altered. The variable part, on the other hand, shows the n- microgrid ﬂexibility in reducing i","equation_id":"Eq. (11)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"D^f_t = \\sum_m d^f_{mt} \\quad \\forall t. \\quad (11)","paper":"34-market_versus_price_scheduling","rule_id":"v141-c-R002","quote":"D^f_t = \\sum_m d^f_{mt} \\quad \\forall t. \\quad (11)"},{"evidence_id":"v141-b-g02-E17","location":{"location_id":"src-b66ae5184e-p05-c2r3__v141-a-M01-bidding","page":5,"printed_page":null,"section":"B. DMO / 1) Bid Aggregation","anchor_text":"or be altered. The variable part, on the other hand, shows the n- microgrid ﬂexibility in reducing i","equation_id":"Eq. (11)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The fixed loads are collectively added to obtain the total fixed load in the DMO service territory (11).\nD_t^{f} = \\sum_m d_{mt}^{f} \\quad \\forall t. \\tag{11}","paper":"34-market_versus_price_scheduling","rule_id":"v141-c-R002","quote":"The fixed loads are collectively added to obtain the total fixed load in the DMO service territory (11).\nD_t^{f} = \\sum_m d_{mt}^{f} \\quad \\forall t. \\tag{11}"},{"evidence_id":"v141-b-g01-e035","location":{"location_id":"src-b66ae5184e-p05-c2r3__v141-a-M01-matching","page":5,"printed_page":null,"section":"B. DMO / 2) Quantity Disaggregation","anchor_text":"or be altered. The variable part, on the other hand, shows the n- microgrid ﬂexibility in reducing i","equation_id":"Eqs. (12)-(13)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Once the ISO determines the awarded power to the DMO, the DMO disaggregates the power to microgrids in its service territory. The DMO maximizes the objective function (12) by determining the optimally allocated power to each microgrid based on the submitted bids.","paper":"34-market_versus_price_scheduling","rule_id":"v141-c-R003","quote":"Once the ISO determines the awarded power to the DMO, the DMO disaggregates the power to microgrids in its service territory. The DMO maximizes the objective function (12) by determining the optimally allocated power to each microgrid based on the submitted bids."},{"evidence_id":"v141-b-g01-e003","location":{"location_id":"src-b66ae5184e-p01-c2r3__v141-a-M01-clearing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"DXmax Segment in the variable load bid of the microgrid. I Commitment state of dispatchable unit (1 ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"d Load demand. D The demand awarded from the ISO to the DMO. PD^M Assigned demand to microgrids by the DMO. DX The amount of load awarded to each segment of the bid. DX^max Segment in the variable load bid of the microgrid. I Commitment state of dispatchable unit (1 when committed, 0 otherwise). LS Load curtailment. P DER output power. P^M Scheduled power transfer from the DMO to the microgrid. PL Line flow. \\Delta P^M Power transfer deviation. \\Delta P^{M+} Positive power transfer deviation. \\delta Power transfer deviation indicator (1 when deviation is positive, 0 otherwise). \\theta Bus angle.","paper":"34-market_versus_price_scheduling","rule_id":"v141-c-R003","quote":"d Load demand. D The demand awarded from the ISO to the DMO. PD^M Assigned demand to microgrids by the DMO. DX The amount of load awarded to each segment of the bid. DX^max Segment in the variable load bid of the microgrid. I Commitment state of dispatchable unit (1 when committed, 0 otherwise). LS Load curtailment. P DER output power. P^M Scheduled power transfer from the DMO to the microgrid. PL Line flow. \\Delta P^M Power transfer deviation. \\Delta P^{M+} Positive power transfer deviation. \\delta Power transfer deviation indicator (1 when deviation is positive, 0 otherwise). \\theta Bus angle."},{"evidence_id":"v141-b-g01-e034","location":{"location_id":"src-b66ae5184e-p05-c2r4__v141-a-M01-matching","page":5,"printed_page":null,"section":"B. DMO / 2) Quantity Disaggregation","anchor_text":"ne max cmjDXmjt (12) d- t m j ch DXmjt ≤DXmaxmj ∀m, ∀t, ∀j (13) he ec- drmt = DXmjt ∀m, ∀t (14) he j","equation_id":"Eqs. (12)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"DX_{mjt} \\le DX^{max}_{mj} \\quad \\forall m, \\forall t, \\forall j \\quad (13)\\nd^r_{mt} = \\sum_j DX_{mjt} \\quad \\forall m, \\forall t \\quad (14)\\nd^f_{mt} + d^r_{mt} = PD^M_{mt} \\quad \\forall m, \\forall t \\quad (15)\\n\\sum_m PD^M_{mt} = D_{bt} \\quad \\forall t \\quad (16)","paper":"34-market_versus_price_scheduling","rule_id":"v141-c-R003","quote":"DX_{mjt} \\le DX^{max}_{mj} \\quad \\forall m, \\forall t, \\forall j \\quad (13)\\nd^r_{mt} = \\sum_j DX_{mjt} \\quad \\forall m, \\forall t \\quad (14)\\nd^f_{mt} + d^r_{mt} = PD^M_{mt} \\quad \\forall m, \\forall t \\quad (15)\\n\\sum_m PD^M_{mt} = D_{bt} \\quad \\forall t \\quad (16)"},{"evidence_id":"v141-b-g01-e036","location":{"location_id":"src-b66ae5184e-p05-c2r4__v141-a-M01-matching","page":5,"printed_page":null,"section":"B. DMO / 2) Quantity Disaggregation","anchor_text":"ne max cmjDXmjt (12) d- t m j ch DXmjt ≤DXmaxmj ∀m, ∀t, ∀j (13) he ec- drmt = DXmjt ∀m, ∀t (14) he j","equation_id":"Eqs. (12)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Constraint (13) guarantees that each segment of load is limited by its maximum. The total responsive demand for each microgrid is the sum of the loads dispatched to each associated segment (14). The awarded load is calculated as the summation of the fixed and responsive loads (15).","paper":"34-market_versus_price_scheduling","rule_id":"v141-c-R003","quote":"Constraint (13) guarantees that each segment of load is limited by its maximum. The total responsive demand for each microgrid is the sum of the loads dispatched to each associated segment (14). The awarded load is calculated as the summation of the fixed and responsive loads (15)."},{"evidence_id":"v141-b-g02-E21","location":{"location_id":"src-b66ae5184e-p06-c1r3__v141-a-M01-clearing","page":6,"printed_page":null,"section":"C. ISO","anchor_text":"the load shifting would require the inclusion of time-coupling m constraints among hourly bids. This","equation_id":"Eq. (17)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"The ISO receives the generation and transmission information from GENCOs and TRANSCOs, and demand bids from DMOs, solves the SCUC problem to determine units schedule followed by a security-constrained optimal power flow to determine unit dispatch, line flow, and LMPs. The ISO’s objective, when considering demand bids, will be to maximize the system social welfare, rather than minimizing the total operation cost, as formulated in (17).","paper":"34-market_versus_price_scheduling","rule_id":"v141-c-R004","quote":"The ISO receives the generation and transmission information from GENCOs and TRANSCOs, and demand bids from DMOs, solves the SCUC problem to determine units schedule followed by a security-constrained optimal power flow to determine unit dispatch, line flow, and LMPs. The ISO’s objective, when considering demand bids, will be to maximize the system social welfare, rather than minimizing the total operation cost, as formulated in (17)."},{"evidence_id":"v141-b-g01-e009","location":{"location_id":"src-b66ae5184e-p03-c2r3__v141-a-M01-bidding","page":3,"printed_page":null,"section":"III. Model Outline","anchor_text":"nd, The discussed DMO in this paper is a platform that enables ts, market activities for end-use cus","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Two major responsibilities of the DMO within this structure are: 1) To receive demand bids from the microgrids (and other responsive loads if any), combine them, and offer an aggregated bid to the ISO...","paper":"34-market_versus_price_scheduling","rule_id":"v141-c-R005","quote":"Two major responsibilities of the DMO within this structure are: 1) To receive demand bids from the microgrids (and other responsive loads if any), combine them, and offer an aggregated bid to the ISO..."},{"evidence_id":"v141-b-g01-e011","location":{"location_id":"src-b66ae5184e-p03-c2r4__v141-a-M01-bidding","page":3,"printed_page":null,"section":"III. Model Outline","anchor_text":"li- vice territory, and subsequently determine microgrids shares ia, from the awarded power. Microgr","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Microgrids would submit their bids to the DMO (in the form of monotonically decreasing demand bids) and later be notified by the DMO on the amount of awarded power (henceforth referred to as the assigned power).","paper":"34-market_versus_price_scheduling","rule_id":"v141-c-R005","quote":"Microgrids would submit their bids to the DMO (in the form of monotonically decreasing demand bids) and later be notified by the DMO on the amount of awarded power (henceforth referred to as the assigned power)."}],"candidate_only":true,"classification_subtypes":["award_based_demand_submission","load_class_conditioned_demand_submission","segmented_demand_bid_submission"],"projection_statuses":["clear"],"taxonomy":{"primary_family":"kind-L3-b3746db7c3","secondary_families":[],"stage":"L3","ontological_kind":"load_class_conditioned_demand_submission"},"semantic_definition":{"definition":"The market participation agent, according to the demand representation rules specified by the source, submits electricity demand with an explicit basis as a demand-side clearing input to the receiving market.","object":"Electricity demand declaration information with an explicit source and representation rules.","inputs":"The demand basis specified by the source and its representation conditions.","operation":"Construct and submit the demand declaration according to the specified representation relation; the specific aggregation and forwarding procedures are retained by the members.","outputs":"Individual or aggregated demand declarations of the receiving market.","boundary":"Retain the demand-side identity and L3/JOC representation and submission boundary of COMP-1e227d383daa7d23; exclude allocated quantity generation, demand allocation, or pricing."},"source_units":[{"unit_id":"18-dlmp_analysis::v141-a-M02::bidding.demand","paper_id":"18-dlmp_analysis","mechanism_id":"v141-a-M02","function":"bidding.demand","source_occurrences":[{"id":"18-dlmp_analysis::v141-c-R004::V::bidding.demand","rule_id":"v141-c-R004","market_meaning":"Aggregators submit demand functions for non-deferrable loads. Scope: Aggregator demand submissions in the distribution-market clearing procedure. Condition: For non-deferrable loads. Aggregators submit multi-part bids representing the energy requirements and technical constraints of deferrable loads. Scope: Aggregator demand submissions in the distribution-market clearing procedure. Condition: For deferrable loads.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Aggregator demand submissions in the distribution-market clearing procedure.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E004"]},"constraint_refs":["18-dlmp_analysis::v141-c-R004::v141-c-R004-C001","18-dlmp_analysis::v141-c-R004::v141-c-R004-C002"],"decision_anchor":"bidding.demand","source_rule_sha256":"82bd0c452b67222caf74aaeb26469a61f6ce0168bf59fb8a2ee30e4fd27a04fa"}],"constraints":[{"constraint_id":"v141-c-R004-C001","kind":"procedural","role":"core","statement":"Aggregators submit demand functions for non-deferrable loads. Scope: Aggregator demand submissions in the distribution-market clearing procedure. Condition: For non-deferrable loads.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E004"],"ref":"18-dlmp_analysis::v141-c-R004::v141-c-R004-C001","source_rule_id":"v141-c-R004","evidence":[{"evidence_id":"v141-b-g01-E004","location":{"location_id":"src-b1966ef5f7-p02-c1r1__v141-a-M02-bidding","page":2,"printed_page":null,"section":"I. Introduction","anchor_text":"PAPAVASILIOU: ANALYSIS OF DISTRIBUTION LOCATIONAL MARGINAL PRICES clearing: (i) aggregators submit d","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"clearing: (i) aggregators submit demand functions for non-deferrable loads and multi-part bids for deferrable loads that represent the energy requirements and technical constraints of deferrable loads"}]},{"constraint_id":"v141-c-R004-C002","kind":"procedural","role":"core","statement":"Aggregators submit multi-part bids representing the energy requirements and technical constraints of deferrable loads. Scope: Aggregator demand submissions in the distribution-market clearing procedure. Condition: For deferrable loads.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E004"],"ref":"18-dlmp_analysis::v141-c-R004::v141-c-R004-C002","source_rule_id":"v141-c-R004","evidence":[{"evidence_id":"v141-b-g01-E004","location":{"location_id":"src-b1966ef5f7-p02-c1r1__v141-a-M02-bidding","page":2,"printed_page":null,"section":"I. Introduction","anchor_text":"PAPAVASILIOU: ANALYSIS OF DISTRIBUTION LOCATIONAL MARGINAL PRICES clearing: (i) aggregators submit d","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"clearing: (i) aggregators submit demand functions for non-deferrable loads and multi-part bids for deferrable loads that represent the energy requirements and technical constraints of deferrable loads"}]}],"variables":[],"parameters":[]},{"unit_id":"23-hierarchical_market_structure::v141-a-M01::bidding.demand","paper_id":"23-hierarchical_market_structure","mechanism_id":"v141-a-M01","function":"bidding.demand","source_occurrences":[{"id":"23-hierarchical_market_structure::v141-c-R007::V::bidding.demand","rule_id":"v141-c-R007","market_meaning":"The LA presents the dispatch awarded by DNEM clearing as a demand quantity at its WEM bus. Scope: LA-mediated submission of DNEM-awarded dispatch as demand at the LA's WEM bus.","omega":{"market_type":"LEM_DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"LA-mediated submission of DNEM-awarded dispatch as demand at the LA's WEM bus.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E005"]},"constraint_refs":["23-hierarchical_market_structure::v141-c-R007::v141-c-R007-C001"],"decision_anchor":"bidding.demand","source_rule_sha256":"fcf96e61e513dea89a7d47c24fcc9e106c145b9c86d8ea77914f447a81629e74"}],"constraints":[{"constraint_id":"v141-c-R007-C001","kind":"procedural","role":"core","statement":"The LA presents the dispatch awarded by DNEM clearing as a demand quantity at its WEM bus. Scope: LA-mediated submission of DNEM-awarded dispatch as demand at the LA's WEM bus.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local","bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E005"],"ref":"23-hierarchical_market_structure::v141-c-R007::v141-c-R007-C001","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g01-E005","location":{"location_id":"src-fbc18f73e3-p03-c1r3__v141-a-M01-participation","page":3,"printed_page":null,"section":"I. Introduction","anchor_text":"composed of these markets. Here, each market participant bids in associated electricity market, whil","equation_id":null,"figure_id":"Fig. 1","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Fig. 1 shows the proposed hierarchical market structure that composed of these markets. Here, each market participant bids in associated electricity market, while each LA is an intermediate agent that participates in both markets to address the synergy of the two markets. The LA bids in the WEM and presents the awarded dispatch in the DNEM as demand on its bus in the WEM. The ISO clears the market and provide the awarded dispatch for the LA and LMP at the LAs bus. The LA bids in the DNEM and presents the awarded dispatch in the WEM as demand on its bus in the DNEM. The DNO clears the market and provide the awarded dispatch for the LA and the market clearing price (MCP) of the market."}]}],"variables":[],"parameters":[]},{"unit_id":"34-market_versus_price_scheduling::v141-a-M01::bidding.demand","paper_id":"34-market_versus_price_scheduling","mechanism_id":"v141-a-M01","function":"bidding.demand","source_occurrences":[{"id":"34-market_versus_price_scheduling::v141-c-R002::V::bidding.demand","rule_id":"v141-c-R002","market_meaning":"The DMO combines received demand bids and submits an aggregated demand bid to the ISO. Scope: DMO aggregation of microgrid and other responsive-load demand bids for submission to the ISO. Microgrid demand bids take a monotonically decreasing form. Scope: Microgrid demand submissions to the DMO. The fixed nonresponsive-load portion of the demand bid cannot be altered. Scope: The fixed nonresponsive-load quantity in a microgrid demand bid. Condition: Under normal operation conditions.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"DMO aggregation of microgrid and other responsive-load demand bids for submission to the ISO. | Microgrid demand submissions to the DMO. | The fixed nonresponsive-load quantity in a microgrid demand bid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e011","v141-b-g01-e037","v141-b-g02-E16"]},"constraint_refs":["34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C001","34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C002","34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C003","34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C004"],"decision_anchor":"bidding.demand","source_rule_sha256":"d98c89cdf0dde2f3a8a6112ca06bc6e5647ab0f9c9f9d58535814c9da2b56144"},{"id":"34-market_versus_price_scheduling::v141-c-R003::V::bidding.demand","rule_id":"v141-c-R003","market_meaning":"Submitted microgrid demand bids provide the inputs on which the DMO bases its local power allocations. Scope: DMO quantity disaggregation among microgrids within its service territory. Condition: Once the ISO has determined the power awarded to the DMO. The maximum quantities in submitted demand-bid segments limit the quantities awarded to those segments. Scope: Responsive demand-bid segment allocations in DMO quantity disaggregation. Condition: Once the ISO has determined the power awarded to the DMO. The DMO performs local allocation by disaggregating its awarded power among microgrids in its service territory. Scope: Allocation of the DMO's awarded power among microgrids in its service territory. Condition: Once the ISO has determined the power awarded to the DMO. Local quantity disaggregation maximizes objective (12), the sum of c_{mj} DX_{mjt} over times, microgrids and bid segments. Scope: DMO quantity-disaggregation optimization within its service territory. Condition: Once the ISO has determined the power awarded to the DMO. Local allocation must fully supply the fixed nonresponsive load represented in each microgrid's bid; that fixed load cannot be altered. Scope: Fixed nonresponsive load represented in microgrid demand bids submitted to the DMO. Condition: Under normal operation conditions. Each microgrid's responsive allocation equals the sum of its dispatched segment quantities, and its total award equals fixed plus responsive load. All microgrid awards sum to the quantity awarded by the ISO to the DMO. Scope: Hourly accounting of DMO power allocations among microgrids in its service territory. Condition: Once the ISO has determined the power awarded to the DMO.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Allocation of the DMO's awarded power among microgrids in its service territory. | DMO quantity disaggregation among microgrids within its service territory. | DMO quantity-disaggregation optimization within its service territory. | Fixed nonresponsive load represented in microgrid demand bids submitted to the DMO. | Hourly accounting of DMO power allocations among microgrids in its service territory. | Responsive demand-bid segment allocations in DMO quantity disaggregation.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e033","v141-b-g01-e034","v141-b-g01-e035","v141-b-g01-e036","v141-b-g02-E16"]},"constraint_refs":["34-market_versus_price_scheduling::v141-c-R003::v141-c-R003-C001","34-market_versus_price_scheduling::v141-c-R003::v141-c-R003-C002"],"decision_anchor":"clearing.local","source_rule_sha256":"ae330c220c9fd0e1cf40e9ec0db7bf57a00793801d2710af7b8b4588d14fdef7"},{"id":"34-market_versus_price_scheduling::v141-c-R004::V::bidding.demand","rule_id":"v141-c-R004","market_meaning":"The ISO's social-welfare clearing objective applies when it considers demand bids. Scope: ISO system-level clearing within the DMO-mediated market-based scheduling arrangement. Condition: When the ISO considers demand bids. The ISO maximizes system social welfare, described as consumption payments minus generation costs, subject to power balance, unit constraints, transmission line limits, and transmission line power flow constraints. Scope: ISO system-level bid-based clearing within the DMO-mediated market-based scheduling arrangement. Condition: When the ISO considers demand bids.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"ISO system-level bid-based clearing within the DMO-mediated market-based scheduling arrangement. | ISO system-level clearing within the DMO-mediated market-based scheduling arrangement.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E21","v141-b-g02-E23"]},"constraint_refs":["34-market_versus_price_scheduling::v141-c-R004::v141-c-R004-C001"],"decision_anchor":"clearing.social_welfare","source_rule_sha256":"c71f84e4f9bebea3d00a8e31ab1798bcbfed50d8572d2a578c5d0fb80262b9aa"},{"id":"34-market_versus_price_scheduling::v141-c-R005::V::bidding.demand","rule_id":"v141-c-R005","market_meaning":"The DMO receives demand bids submitted by microgrids and other responsive loads, if any. Scope: Demand-bid receipt in the DMO-administered distribution market, covering microgrids and other responsive loads if any. The DMO may be formed as a new entity or as part of existing electric utilities. Scope: Institutional formation of the proposed DMO. An independent DMO may establish a universal market environment instead of a separate environment for each utility. Scope: Market establishment by an independent DMO. Condition: The DMO is independent.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Demand-bid receipt in the DMO-administered distribution market, covering microgrids and other responsive loads if any. | Institutional formation of the proposed DMO. | Market establishment by an independent DMO.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e011","v141-b-g02-E02"]},"constraint_refs":["34-market_versus_price_scheduling::v141-c-R005::v141-c-R005-C001"],"decision_anchor":"coordination.local_operator","source_rule_sha256":"87b82451f61ecc37c9ca2ef2fa4fdff8af0624843a1cc0ef6aa8a1c2f8baa3d8"}],"constraints":[{"constraint_id":"v141-c-R002-C001","kind":"procedural","role":"core","statement":"The DMO combines received demand bids and submits an aggregated demand bid to the ISO. Scope: DMO aggregation of microgrid and other responsive-load demand bids for submission to the ISO.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e037"],"ref":"34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C001","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g01-e009","location":{"location_id":"src-b66ae5184e-p03-c2r3__v141-a-M01-bidding","page":3,"printed_page":null,"section":"III. Model Outline","anchor_text":"nd, The discussed DMO in this paper is a platform that enables ts, market activities for end-use cus","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Two major responsibilities of the DMO within this structure are: 1) To receive demand bids from the microgrids (and other responsive loads if any), combine them, and offer an aggregated bid to the ISO..."},{"evidence_id":"v141-b-g01-e037","location":{"location_id":"src-b66ae5184e-p05-c2r2__v141-a-M01-bidding","page":5,"printed_page":null,"section":"B. DMO / 1) Bid Aggregation","anchor_text":"ed is o- Fig. 2. Demand bid curve for microgrid m with a three-segment bid. by B. DMO nal es The DMO","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"The DMO seeks two objectives: first, to combine individual bids received from microgrids in its territory to create an aggregated bid and accordingly send the aggregated bid to the ISO to participate in the energy market; second, to disaggregate the awarded quantity by the ISO to individual microgrids in accordance with their respective bids."}]},{"constraint_id":"v141-c-R002-C002","kind":"procedural","role":"core","statement":"Microgrid demand bids take a monotonically decreasing form. Scope: Microgrid demand submissions to the DMO.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e011"],"ref":"34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C002","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g01-e011","location":{"location_id":"src-b66ae5184e-p03-c2r4__v141-a-M01-bidding","page":3,"printed_page":null,"section":"III. Model Outline","anchor_text":"li- vice territory, and subsequently determine microgrids shares ia, from the awarded power. Microgr","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Microgrids would submit their bids to the DMO (in the form of monotonically decreasing demand bids) and later be notified by the DMO on the amount of awarded power (henceforth referred to as the assigned power)."}]},{"constraint_id":"v141-c-R002-C003","kind":"procedural","role":"core","statement":"The fixed nonresponsive-load portion of the demand bid cannot be altered. Scope: The fixed nonresponsive-load quantity in a microgrid demand bid. Condition: Under normal operation conditions.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E16"],"ref":"34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C003","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g02-E16","location":{"location_id":"src-b66ae5184e-p05-c2r2__v141-a-M01-bidding","page":5,"printed_page":null,"section":"B. DMO / 1) Bid Aggregation","anchor_text":"ed is o- Fig. 2. Demand bid curve for microgrid m with a three-segment bid. by B. DMO nal es The DMO","equation_id":"Eq. (11)","figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Fig. 2 depicts a typical demand bid curve submitted by a microgrid to the DMO at a specific hour t. The bid consists of fixed and variable parts. The fixed part shows the microgrid nonresponsive load which must be fully supplied under normal operation conditions and cannot be altered. The variable part, on the other hand, shows the microgrid flexibility in reducing its consumption from its total load. It consists of several segments. The reduction in consumption can be achieved either via load curtailment or local DER generation. The DMO combines the individual microgrid bids and obtains an aggregated bid to be sent to the ISO. The fixed loads are collectively added to obtain the total fixed load in the DMO service territory (11)."}]},{"constraint_id":"v141-c-R002-C004","kind":"mathematical","role":"supporting","statement":"The DMO obtains the total fixed nonresponsive load in its service territory at hour t by summing the fixed nonresponsive loads of the individual microgrid demand bids.","expression":"D^f_t = \\sum_m d^f_{mt} \\quad \\forall t.","formalization_origin":"source","template_id":null,"members":["coordination.local_operator","bidding.demand"],"variable_refs":[],"parameter_refs":["v141-c-R002-theta-df-mt","v141-c-R002-theta-Df-t"],"evidence_ids":["v141-b-g01-e032","v141-b-g02-E16","v141-b-g02-E17"],"ref":"34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C004","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g01-e032","location":{"location_id":"src-b66ae5184e-p05-c2r3__v141-a-M01-bidding","page":5,"printed_page":null,"section":"B. DMO / 1) Bid Aggregation","anchor_text":"or be altered. The variable part, on the other hand, shows the n- microgrid ﬂexibility in reducing i","equation_id":"Eq. (11)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"D^f_t = \\sum_m d^f_{mt} \\quad \\forall t. \\quad (11)"},{"evidence_id":"v141-b-g02-E16","location":{"location_id":"src-b66ae5184e-p05-c2r2__v141-a-M01-bidding","page":5,"printed_page":null,"section":"B. DMO / 1) Bid Aggregation","anchor_text":"ed is o- Fig. 2. Demand bid curve for microgrid m with a three-segment bid. by B. DMO nal es The DMO","equation_id":"Eq. (11)","figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Fig. 2 depicts a typical demand bid curve submitted by a microgrid to the DMO at a specific hour t. The bid consists of fixed and variable parts. The fixed part shows the microgrid nonresponsive load which must be fully supplied under normal operation conditions and cannot be altered. The variable part, on the other hand, shows the microgrid flexibility in reducing its consumption from its total load. It consists of several segments. The reduction in consumption can be achieved either via load curtailment or local DER generation. The DMO combines the individual microgrid bids and obtains an aggregated bid to be sent to the ISO. The fixed loads are collectively added to obtain the total fixed load in the DMO service territory (11)."},{"evidence_id":"v141-b-g02-E17","location":{"location_id":"src-b66ae5184e-p05-c2r3__v141-a-M01-bidding","page":5,"printed_page":null,"section":"B. DMO / 1) Bid Aggregation","anchor_text":"or be altered. The variable part, on the other hand, shows the n- microgrid ﬂexibility in reducing i","equation_id":"Eq. (11)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The fixed loads are collectively added to obtain the total fixed load in the DMO service territory (11).\nD_t^{f} = \\sum_m d_{mt}^{f} \\quad \\forall t. \\tag{11}"}]},{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"Submitted microgrid demand bids provide the inputs on which the DMO bases its local power allocations. Scope: DMO quantity disaggregation among microgrids within its service territory. Condition: Once the ISO has determined the power awarded to the DMO.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e035"],"ref":"34-market_versus_price_scheduling::v141-c-R003::v141-c-R003-C001","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g01-e035","location":{"location_id":"src-b66ae5184e-p05-c2r3__v141-a-M01-matching","page":5,"printed_page":null,"section":"B. DMO / 2) Quantity Disaggregation","anchor_text":"or be altered. The variable part, on the other hand, shows the n- microgrid ﬂexibility in reducing i","equation_id":"Eqs. (12)-(13)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Once the ISO determines the awarded power to the DMO, the DMO disaggregates the power to microgrids in its service territory. The DMO maximizes the objective function (12) by determining the optimally allocated power to each microgrid based on the submitted bids."}]},{"constraint_id":"v141-c-R003-C002","kind":"mathematical","role":"core","statement":"The maximum quantities in submitted demand-bid segments limit the quantities awarded to those segments. Scope: Responsive demand-bid segment allocations in DMO quantity disaggregation. Condition: Once the ISO has determined the power awarded to the DMO.","expression":"DX_{mjt} \\le DX^{max}_{mj} \\quad \\forall m, \\forall t, \\forall j \\quad (13)","formalization_origin":"source","template_id":null,"members":["bidding.demand","clearing.local"],"variable_refs":["v141-c-R003-x-DX"],"parameter_refs":["v141-c-R003-theta-DXmax"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e034","v141-b-g01-e036"],"ref":"34-market_versus_price_scheduling::v141-c-R003::v141-c-R003-C002","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g01-e003","location":{"location_id":"src-b66ae5184e-p01-c2r3__v141-a-M01-clearing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"DXmax Segment in the variable load bid of the microgrid. I Commitment state of dispatchable unit (1 ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"d Load demand. D The demand awarded from the ISO to the DMO. PD^M Assigned demand to microgrids by the DMO. DX The amount of load awarded to each segment of the bid. DX^max Segment in the variable load bid of the microgrid. I Commitment state of dispatchable unit (1 when committed, 0 otherwise). LS Load curtailment. P DER output power. P^M Scheduled power transfer from the DMO to the microgrid. PL Line flow. \\Delta P^M Power transfer deviation. \\Delta P^{M+} Positive power transfer deviation. \\delta Power transfer deviation indicator (1 when deviation is positive, 0 otherwise). \\theta Bus angle."},{"evidence_id":"v141-b-g01-e034","location":{"location_id":"src-b66ae5184e-p05-c2r4__v141-a-M01-matching","page":5,"printed_page":null,"section":"B. DMO / 2) Quantity Disaggregation","anchor_text":"ne max cmjDXmjt (12) d- t m j ch DXmjt ≤DXmaxmj ∀m, ∀t, ∀j (13) he ec- drmt = DXmjt ∀m, ∀t (14) he j","equation_id":"Eqs. (12)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"DX_{mjt} \\le DX^{max}_{mj} \\quad \\forall m, \\forall t, \\forall j \\quad (13)\\nd^r_{mt} = \\sum_j DX_{mjt} \\quad \\forall m, \\forall t \\quad (14)\\nd^f_{mt} + d^r_{mt} = PD^M_{mt} \\quad \\forall m, \\forall t \\quad (15)\\n\\sum_m PD^M_{mt} = D_{bt} \\quad \\forall t \\quad (16)"},{"evidence_id":"v141-b-g01-e036","location":{"location_id":"src-b66ae5184e-p05-c2r4__v141-a-M01-matching","page":5,"printed_page":null,"section":"B. DMO / 2) Quantity Disaggregation","anchor_text":"ne max cmjDXmjt (12) d- t m j ch DXmjt ≤DXmaxmj ∀m, ∀t, ∀j (13) he ec- drmt = DXmjt ∀m, ∀t (14) he j","equation_id":"Eqs. (12)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Constraint (13) guarantees that each segment of load is limited by its maximum. The total responsive demand for each microgrid is the sum of the loads dispatched to each associated segment (14). The awarded load is calculated as the summation of the fixed and responsive loads (15)."}]},{"constraint_id":"v141-c-R004-C001","kind":"logical","role":"core","statement":"The ISO's social-welfare clearing objective applies when it considers demand bids. Scope: ISO system-level clearing within the DMO-mediated market-based scheduling arrangement. Condition: When the ISO considers demand bids.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.social_welfare","bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E21"],"ref":"34-market_versus_price_scheduling::v141-c-R004::v141-c-R004-C001","source_rule_id":"v141-c-R004","evidence":[{"evidence_id":"v141-b-g02-E21","location":{"location_id":"src-b66ae5184e-p06-c1r3__v141-a-M01-clearing","page":6,"printed_page":null,"section":"C. ISO","anchor_text":"the load shifting would require the inclusion of time-coupling m constraints among hourly bids. This","equation_id":"Eq. (17)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"The ISO receives the generation and transmission information from GENCOs and TRANSCOs, and demand bids from DMOs, solves the SCUC problem to determine units schedule followed by a security-constrained optimal power flow to determine unit dispatch, line flow, and LMPs. The ISO’s objective, when considering demand bids, will be to maximize the system social welfare, rather than minimizing the total operation cost, as formulated in (17)."}]},{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"The DMO receives demand bids submitted by microgrids and other responsive loads, if any. Scope: Demand-bid receipt in the DMO-administered distribution market, covering microgrids and other responsive loads if any.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e011"],"ref":"34-market_versus_price_scheduling::v141-c-R005::v141-c-R005-C001","source_rule_id":"v141-c-R005","evidence":[{"evidence_id":"v141-b-g01-e009","location":{"location_id":"src-b66ae5184e-p03-c2r3__v141-a-M01-bidding","page":3,"printed_page":null,"section":"III. Model Outline","anchor_text":"nd, The discussed DMO in this paper is a platform that enables ts, market activities for end-use cus","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Two major responsibilities of the DMO within this structure are: 1) To receive demand bids from the microgrids (and other responsive loads if any), combine them, and offer an aggregated bid to the ISO..."},{"evidence_id":"v141-b-g01-e011","location":{"location_id":"src-b66ae5184e-p03-c2r4__v141-a-M01-bidding","page":3,"printed_page":null,"section":"III. Model Outline","anchor_text":"li- vice territory, and subsequently determine microgrids shares ia, from the awarded power. Microgr","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Microgrids would submit their bids to the DMO (in the form of monotonically decreasing demand bids) and later be notified by the DMO on the amount of awarded power (henceforth referred to as the assigned power)."}]}],"variables":[{"variable_id":"v141-c-R003-x-DX","symbol":"DX_{mjt}","meaning":"Amount of load awarded to each segment j of microgrid m's demand bid at hour t in the DMO's local quantity disaggregation.","kind":"operational","domain":"Source-defined segment load award; Eq. (13) supplies the upper bound DX^{max}_{mj}, and no explicit lower bound is stated in the supplied evidence.","unit":null,"indices":["m","t","j"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e034","v141-b-g01-e036"],"source_rule_id":"v141-c-R003","declaration_ref":"34-market_versus_price_scheduling::v141-c-R003::x::v141-c-R003-x-DX"}],"parameters":[{"parameter_id":"v141-c-R002-theta-df-mt","symbol":"d^{f}_{mt}","meaning":"Fixed nonresponsive load included in microgrid m's demand bid at hour t; the fixed part of the bid that must be fully supplied under normal operation and cannot be altered.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["m","t"],"evidence_ids":["v141-b-g01-e031","v141-b-g01-e032","v141-b-g02-E16","v141-b-g02-E17"],"source_rule_id":"v141-c-R002","declaration_ref":"34-market_versus_price_scheduling::v141-c-R002::theta::v141-c-R002-theta-df-mt"},{"parameter_id":"v141-c-R002-theta-Df-t","symbol":"D^{f}_{t}","meaning":"Total fixed nonresponsive load of all microgrids in the DMO service territory at hour t, obtained by summing the microgrid fixed loads in the aggregated bid.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g01-e032","v141-b-g02-E16","v141-b-g02-E17"],"source_rule_id":"v141-c-R002","declaration_ref":"34-market_versus_price_scheduling::v141-c-R002::theta::v141-c-R002-theta-Df-t"},{"parameter_id":"v141-c-R003-theta-DXmax","symbol":"DX^{max}_{mj}","meaning":"Maximum quantity of load in bid segment j of microgrid m; Eq. (13) limits each dispatched segment award by this value.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["m","j"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e034","v141-b-g01-e036"],"source_rule_id":"v141-c-R003","declaration_ref":"34-market_versus_price_scheduling::v141-c-R003::theta::v141-c-R003-theta-DXmax"}]}],"source_definitions":[{"unit_id":"18-dlmp_analysis::v141-a-M02::bidding.demand","stage":"L3","subtype":"load_class_conditioned_demand_submission","projection_status":"clear","target_definition":"The aggregator submits a demand function for non-deferrable load and, for deferrable load, a multi-part bid representing energy demand and technical constraints.","form_kind":"procedural","identity_fields":["Object: load demand declaration information","Core operation: select the declaration form according to load deferrability","Output: demand function for non-deferrable load and multi-part bid for deferrable load"],"variation_fields":["Declaring entity: aggregator","Use scenario: distribution market clearing","Content of deferrable load bid: energy demand and technical constraints"],"constraint_refs":["18-dlmp_analysis::v141-c-R004::v141-c-R004-C001","18-dlmp_analysis::v141-c-R004::v141-c-R004-C002"],"paper_id":"18-dlmp_analysis","mechanism_id":"v141-a-M02","function":"bidding.demand","template_code":"JOC"},{"unit_id":"23-hierarchical_market_structure::v141-a-M01::bidding.demand","stage":"L3","subtype":"award_based_demand_submission","projection_status":"clear","target_definition":"LA submits the dispatch quantity obtained from DNEM clearing as the demand quantity at its WEM connection bus.","form_kind":"procedural","identity_fields":["Object: allocated dispatch quantity of another market","Core relation: declare the allocated quantity as node demand in the target market","Output: node demand quantity"],"variation_fields":["Submitter: LA","Direction: DNEM allocated quantity converted to WEM bus demand","The submitted quantity depends on the obtained clearing result"],"constraint_refs":["23-hierarchical_market_structure::v141-c-R007::v141-c-R007-C001"],"paper_id":"23-hierarchical_market_structure","mechanism_id":"v141-a-M01","function":"bidding.demand","template_code":"JOC"},{"unit_id":"34-market_versus_price_scheduling::v141-a-M01::bidding.demand","stage":"L3","subtype":"segmented_demand_bid_submission","projection_status":"clear","target_definition":"Microgrids submit monotonically decreasing demand bids to the DMO, including fixed non-responsive load and segmented responsive demand, with each segment providing a maximum quantity DX^{max}_{mj}. After aggregation, the DMO reports to the ISO, where D^f_t = ∑_m d^f_{mt}; under normal operation, the fixed portion cannot be changed.","form_kind":"procedural","identity_fields":["Object: demand bid curve and its quantity information","Core operation: submit individual demand bids and aggregate and report them","Output: individual and aggregated bids containing fixed load and responsive segments"],"variation_fields":["The submitters are microgrids and possibly other responsive loads","The receiver and aggregator is the DMO; the reporting target is the ISO","Monotonically decreasing curve, segment quantity upper limits, and hourly index","Under normal operation, fixed load must be supplied in full and cannot be changed","Response capability may come from load curtailment or local DER generation"],"constraint_refs":["34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C001","34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C002","34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C003","34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C004","34-market_versus_price_scheduling::v141-c-R003::v141-c-R003-C002","34-market_versus_price_scheduling::v141-c-R005::v141-c-R005-C001"],"paper_id":"34-market_versus_price_scheduling","mechanism_id":"v141-a-M01","function":"bidding.demand","template_code":"JOC"}],"source_variants":[{"unit_id":"18-dlmp_analysis::v141-a-M02::bidding.demand","source_definition":"The aggregator submits a demand function for non-deferrable load and, for deferrable load, a multi-part bid representing energy demand and technical constraints.","retained_variants":["The submitter is the aggregator.","Non-deferrable load uses a demand function.","Deferrable load uses a multi-part bid containing energy demand and technical constraints."],"constraint_refs":["18-dlmp_analysis::v141-c-R004::v141-c-R004-C001","18-dlmp_analysis::v141-c-R004::v141-c-R004-C002"]},{"unit_id":"23-hierarchical_market_structure::v141-a-M01::bidding.demand","source_definition":"LA submits the dispatch quantity obtained from DNEM clearing as the demand quantity at its WEM connection bus.","retained_variants":["The submitter is LA; the direction is from the DNEM allocated quantity to WEM bus demand.","The declaration depends on the dispatch result already obtained.","The reverse submission in the complete quotation does not expand the target projection of this member."],"constraint_refs":["23-hierarchical_market_structure::v141-c-R007::v141-c-R007-C001"]},{"unit_id":"34-market_versus_price_scheduling::v141-a-M01::bidding.demand","source_definition":"Microgrids submit monotonically decreasing demand bids to the DMO, including fixed non-responsive load and segmented responsive demand, with each segment providing a maximum quantity DX^{max}_{mj}. After aggregation, the DMO reports to the ISO, where D^f_t=∑_m d^f_{mt}; under normal operation, the fixed portion cannot be changed.","retained_variants":["Microgrids and possibly other responsive loads submit; the DMO receives, aggregates, and reports to the ISO.","The bid is monotonically decreasing; under normal operation, the fixed portion must be supplied in full and cannot be changed.","Fixed load is aggregated according to D^f_t=∑_m d^f_{mt}; each response segment retains DX^{max}_{mj}.","Response capability may come from load curtailment or local DER; the allocated quantity DX_{mjt} and subsequent allocation optimization are not declaration fields."],"constraint_refs":["34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C001","34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C002","34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C003","34-market_versus_price_scheduling::v141-c-R002::v141-c-R002-C004","34-market_versus_price_scheduling::v141-c-R003::v141-c-R003-C002","34-market_versus_price_scheduling::v141-c-R005::v141-c-R005-C001"]}],"source_parent_definition":{"definition":"The market participation agent, according to the demand representation rules specified by the source, submits electricity demand with an explicit basis as a demand-side clearing input to the receiving market.","object":"Electricity demand declaration information with an explicit source and representation rules.","inputs":"The demand basis specified by the source and its representation conditions.","operation":"Construct and submit the demand declaration according to the specified representation relation; the specific aggregation and forwarding procedures are retained by the members.","outputs":"Individual or aggregated demand declarations of the receiving market.","boundary":"Retain the demand-side identity and L3/JOC representation and submission boundary of COMP-1e227d383daa7d23; exclude allocated quantity generation, demand allocation, or pricing."},"functional":{"is_child":false,"subdivision_pending":true,"baseline_parent_id":"COMP-234e316a4df6b1c7","baseline_parent_code":"BID016","category":{},"definition":{}},"canonical_pointer":"/nodes/34"});
